<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';import {api} from './api';import MathText from './MathText.vue';import QuestionContent from './QuestionContent.vue';
const courses=ref([]),papers=ref([]),meta=ref({terms:[],exams:[]}),course=ref(''),paper=ref(''),term=ref(''),exam=ref(''),kind=ref(''),solutionStatus=ref(''),page=ref(1),total=ref(0),items=ref([]),batches=ref([]),counts=ref({}),selected=ref([]),error=ref(''),notice=ref(''),busy=ref(false),preview=ref(null),editText=ref('');let timer,stopped=false;
const publishable=computed(()=>selected.value.length>0&&selected.value.every(id=>items.value.some(i=>i.question_id===id&&['CHECKS_PASSED','DRAFT'].includes(i.solution?.status))));
async function load(){const d=await api('/admin/ai-solutions?'+new URLSearchParams({course_id:course.value,paper_id:paper.value,term_id:term.value,exam_type_id:exam.value,kind:kind.value,solution_status:solutionStatus.value,page:page.value}));if(stopped)return;items.value=d.items;total.value=d.total;batches.value=d.batches;counts.value=d.counts}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function filter(){page.value=1;selected.value=[];await run(load)}
async function chooseCourse(){try{paper.value='';let n=1,all=[],d;do{d=await api('/admin/papers?limit=100&course_id='+course.value+'&page='+n++);all.push(...d.items)}while(course.value&&all.length<d.total&&d.items.length);papers.value=all;await filter()}catch(e){error.value=e.message}}
async function queue(limit=30,regenerate=false,ids=selected.value){await run(async()=>{if(!paper.value&&!ids.length)throw Error('Select a paper or questions.');const d=await api('/admin/ai-solutions/queue',{method:'POST',body:{limit,regenerate,term_id:term.value,exam_type_id:exam.value,kind:kind.value,...(ids.length?{question_ids:ids}:{paper_id:Number(paper.value)})}});notice.value=d.queued+' questions queued. Start your PC worker to process them.';selected.value=[]})}
async function action(qid,action,text){await run(()=>api('/admin/ai-solutions/'+qid,{method:'POST',body:{action,text}}));if(action==='edit')preview.value=null}
async function bulkPublish(){await run(async()=>{for(const id of selected.value)await api('/admin/ai-solutions/'+id,{method:'POST',body:{action:'publish'}});selected.value=[]})}
onMounted(async()=>{await run(async()=>{courses.value=(await api('/catalog')).courses||[];meta.value=await api('/metadata');await chooseCourse()});timer=setInterval(()=>{if(!busy.value)load().catch(e=>error.value=e.message)},30000)});
onUnmounted(()=>{stopped=true;clearInterval(timer)});
</script>
<template><section class="panel"><h2>AI Solutions</h2><p>Generation runs on your PC, never in student requests. Start the local worker, queue a batch, inspect drafts, then publish. Source answer keys are unchanged.</p><p v-if="error" class="alert alert-danger">{{error}}</p><p v-if="notice" class="alert alert-success">{{notice}}</p><div class="filters flex-wrap"><select class="form-select" v-model="course" @change="chooseCourse"><option value="">All courses</option><option v-for="c in courses" :value="c.id">{{c.name}}</option></select><select class="form-select" v-model="paper" @change="filter"><option value="">Select paper</option><option v-for="p in papers" :value="p.id">{{p.term}} · {{p.exam}} · {{p.name}}</option></select><select class="form-select" v-model="term" @change="filter"><option value="">All terms</option><option v-for="t in meta.terms" :value="t.id">{{t.name}}</option></select><select class="form-select" v-model="exam" @change="filter"><option value="">All exams</option><option v-for="e in meta.exams" :value="e.id">{{e.name}}</option></select><select class="form-select" v-model="kind" @change="filter"><option value="">All types</option><option v-for="k in ['MCQ','MSQ','NAT','TRUE_FALSE','SUBJECTIVE','CODE','IMAGE']">{{k}}</option></select><select class="form-select" v-model="solutionStatus" @change="filter"><option value="">All solution states</option><option v-for="s in ['NOT_GENERATED','CHECKS_PASSED','NEEDS_REVIEW','DRAFT','PUBLISHED']" :value="s">{{s.replaceAll('_',' ')}}</option></select></div><div class="d-flex flex-wrap gap-3 mb-3"><span v-for="(n,status) in counts" class="status">{{status.replaceAll('_',' ')}}: {{n}}</span></div><div class="d-flex flex-wrap gap-2"><button class="btn btn-light" :disabled="busy" @click="queue(5)">Generate 5 samples</button><button class="btn btn-primary" :disabled="busy" @click="queue(30)">Generate next 30 / selected</button><button class="btn btn-light" :disabled="busy||!publishable" @click="bulkPublish">Publish selected drafts</button><button class="btn btn-light" :disabled="busy" @click="run(load)">Refresh</button></div><p class="muted mt-3">Checks passed means source-key and format checks passed; it does not certify that the AI reasoning is correct. Review before publishing.</p></section><article v-for="b in batches" class="panel mt-3"><strong>Batch #{{b.id}} · {{b.status}} · {{b.worker_online?'Worker online':'Worker offline / no recent heartbeat'}}</strong><p><span v-for="(n,status) in b.counts" class="me-3">{{status.replaceAll('_',' ')}}: {{n}}</span></p><progress aria-label="Solution generation progress" :max="Object.values(b.counts).reduce((a,v)=>a+v,0)||1" :value="(b.counts.DONE||0)+(b.counts.FAILED||0)+(b.counts.OUTDATED||0)"></progress><span class="mx-2">{{Math.round(((b.counts.DONE||0)+(b.counts.FAILED||0)+(b.counts.OUTDATED||0))*100/(Object.values(b.counts).reduce((a,v)=>a+v,0)||1))}}%</span><button class="btn btn-light" :disabled="busy" @click="run(()=>api('/admin/ai-solutions/batches/'+b.id,{method:'POST',body:{action:b.status==='RUNNING'?'pause':'resume'}}))">{{b.status==='RUNNING'?'Pause':'Resume'}}</button></article><article v-for="i in items" :key="i.question_id" class="panel mt-3"><label><input type="checkbox" :value="i.question_id" v-model="selected"> Q{{i.number}} · {{i.kind}} · {{i.solution?.status||'Not generated'}} · {{i.job?.status}}</label><p v-if="i.job?.error">{{i.job.error}} ({{i.job.attempts}} attempts)</p><div class="d-flex flex-wrap gap-2"><button class="btn btn-light" @click="preview=i;editText=i.solution?.text||''">Preview / edit</button><button class="btn btn-light" :disabled="busy" @click="queue(1,true,[i.question_id])">Regenerate / retry</button><button v-if="i.solution&&['CHECKS_PASSED','DRAFT'].includes(i.solution.status)" class="btn btn-primary" :disabled="busy" @click="action(i.question_id,'publish')">Publish</button><button v-if="i.solution?.status==='PUBLISHED'" class="btn btn-light" :disabled="busy" @click="action(i.question_id,'unpublish')">Unpublish</button></div></article><div class="pagination-row"><button class="btn btn-light" :disabled="page===1||busy" @click="page--;run(load)">Previous</button><span>{{page}} · {{total}} questions</span><button class="btn btn-light" :disabled="page*24>=total||busy" @click="page++;run(load)">Next</button></div><div v-if="preview" class="modal-backdrop-custom"><section class="panel modal-panel ai-solution-editor" role="dialog" aria-modal="true"><h2>Question {{preview.number}}</h2><QuestionContent :text="[preview.question.passage,preview.question.text].filter(Boolean).join('\n\n')" :images="preview.question.images.filter(i=>!i.option_key)"/><div v-for="o in preview.question.options"><strong>{{o.key}}:</strong><QuestionContent :text="o.text" :images="preview.question.images.filter(i=>i.option_key===o.key)"/></div><p>Source answer: {{preview.question.answers}}</p><p v-for="c in preview.solution?.checks" class="alert alert-warning">{{c}}</p><textarea class="form-control" rows="10" maxlength="14000" v-model="editText"></textarea><MathText :text="editText"/><button v-if="preview.solution&&preview.solution.status!=='OUTDATED'" class="btn btn-primary" :disabled="busy" @click="action(preview.question_id,'edit',editText)">Save draft</button><button class="btn btn-light" @click="preview=null">Close</button></section></div></template>
